"""Renders legal/*.md into: site/ (static pages for GitHub Pages), server/src/legal_pages.ts (served by the Worker),
and app/src/legal/licenses.json (the in-app Licenses screen). Run: python3 legal/tools/build.py"""
import json, os, re, html, markdown
ROOT = os.path.normpath(os.path.join(os.path.dirname(__file__), "..", ".."))
L = os.path.join(ROOT, "legal")
V = json.load(open(os.path.join(L, "vars.json")))
LJ = json.load(open(os.path.join(L, "licenses.json")))
sub = lambda s: re.sub(r"\{\{(\w+)\}\}", lambda m: V[m.group(1)], s)

MIT = """Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:

The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE."""
ISC = """Permission to use, copy, modify, and/or distribute this software for any purpose with or without fee is hereby granted, provided that the above copyright notice and this permission notice appear in all copies.

THE SOFTWARE IS PROVIDED "AS IS" AND THE AUTHOR DISCLAIMS ALL WARRANTIES WITH REGARD TO THIS SOFTWARE INCLUDING ALL IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS. IN NO EVENT SHALL THE AUTHOR BE LIABLE FOR ANY SPECIAL, DIRECT, INDIRECT, OR CONSEQUENTIAL DAMAGES OR ANY DAMAGES WHATSOEVER RESULTING FROM LOSS OF USE, DATA OR PROFITS, WHETHER IN AN ACTION OF CONTRACT, NEGLIGENCE OR OTHER TORTIOUS ACTION, ARISING OUT OF OR IN CONNECTION WITH THE USE OR PERFORMANCE OF THIS SOFTWARE."""
BSD2 = """Redistribution and use in source and binary forms, with or without modification, are permitted provided that the following conditions are met:

1. Redistributions of source code must retain the above copyright notice, this list of conditions and the following disclaimer.
2. Redistributions in binary form must reproduce the above copyright notice, this list of conditions and the following disclaimer in the documentation and/or other materials provided with the distribution.

THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS "AS IS" AND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE ARE DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT HOLDER OR CONTRIBUTORS BE LIABLE FOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR CONSEQUENTIAL DAMAGES (INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF SUBSTITUTE GOODS OR SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS INTERRUPTION) HOWEVER CAUSED AND ON ANY THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT LIABILITY, OR TORT (INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY OUT OF THE USE OF THIS SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE."""
BSD3 = BSD2.replace("distribution.\n\n", "distribution.\n3. Neither the name of the copyright holder nor the names of its contributors may be used to endorse or promote products derived from this software without specific prior written permission.\n\n", 1)
BSL = """Permission is hereby granted, free of charge, to any person or organization obtaining a copy of the software and accompanying documentation covered by this license (the "Software") to use, reproduce, display, distribute, execute, and transmit the Software, and to prepare derivative works of the Software, and to permit third-parties to whom the Software is furnished to do so, all subject to the following:

The copyright notices in the Software and this entire statement, including the above license grant, this restriction and the following disclaimer, must be included in all copies of the Software, in whole or in part, and all derivative works of the Software, unless such copies or derivative works are solely in the form of machine-executable object code generated by a source language processor.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE, TITLE AND NON-INFRINGEMENT. IN NO EVENT SHALL THE COPYRIGHT HOLDERS OR ANYONE DISTRIBUTING THE SOFTWARE BE LIABLE FOR ANY DAMAGES OR OTHER LIABILITY, WHETHER IN CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE."""
APACHE = open("/usr/share/common-licenses/Apache-2.0").read().strip()
ofl_path = os.path.join(ROOT, "app/node_modules/@expo-google-fonts/manrope/LICENSE_FONT")
OFL = open(ofl_path).read().strip() if os.path.exists(ofl_path) else "SIL Open Font License, Version 1.1 — https://openfontlicense.org"
OFL = re.sub(r"^.*?(?=This Font Software is licensed)", "", OFL, flags=re.S).strip() or OFL
TEXTS = {"MIT": MIT, "ISC": ISC, "BSD-2-Clause": BSD2, "BSD-3-Clause": BSD3, "BSL-1.0": BSL, "Apache-2.0": APACHE, "OFL-1.1": OFL}
KNOWN = {"metro-runtime": "Copyright (c) Meta Platforms, Inc. and affiliates.", "@react-native/": "Copyright (c) Meta Platforms, Inc. and affiliates.", "react": "Copyright (c) Meta Platforms, Inc. and affiliates."}

def notice(p):
    lines = [l.strip() for l in p["text"].splitlines() if re.match(r"\s*(Copyright|\(c\)|©)", l, re.I)]
    if lines: return " ".join(dict.fromkeys(lines))[:400]
    for k, v in KNOWN.items():
        if p["name"].startswith(k): return v
    pj = os.path.join(ROOT, "app/node_modules", p["name"], "package.json")
    a = json.load(open(pj)).get("author") if os.path.exists(pj) else None
    a = a.get("name") if isinstance(a, dict) else a
    return f"Copyright (c) {re.sub(r' <.*?>| \(.*?\)', '', a)}" if a else "Copyright (c) the authors"

rows = [{"name": p["name"], "version": p["version"], "license": p["license"], "notice": notice(p)} for p in LJ["packages"]]
native = LJ["native"]; fonts = LJ["fonts"]
used = sorted({t for r in rows for t in re.split(r"\s+(?:AND|OR)\s+|[()]", r["license"]) if t} | {n["license"] for n in native + fonts})

def lic_md():
    out = [f"---\ntitle: Licenses\nslug: licenses\n---\n# Open-source licenses\n\n**Updated {V['EFFECTIVE']}**\n\n{V['APP']} is built with open-source software. We are grateful to its authors. Each component below is used under the license shown, and the full text of each license follows. Nothing in our Terms limits your rights under these licenses.\n",
           "## Market data\n\nCryptocurrency market data provided by [CoinGecko](https://www.coingecko.com). CoinGecko is not responsible for this app or its calculations.\n",
           "## Fonts\n", "| Font | License | Notice |\n|---|---|---|"]
    out += [f"| {f['name']} | {f['license']} | {f['notice']} |" for f in fonts]
    out += ["\n## Native libraries (iOS)\n", "| Library | License | Notice |\n|---|---|---|"]
    out += [f"| {n['name']} | {n['license']} | {html.escape(n['notice'])} |" for n in native]
    out += [f"\n## JavaScript packages ({len(rows)})\n", "| Package | Version | License | Notice |\n|---|---|---|---|"]
    out += [f"| {r['name']} | {r['version']} | {r['license']} | {html.escape(r['notice']).replace('|','/')} |" for r in rows]
    out += ["\n## License texts\n"]
    for t in used:
        if t in TEXTS: out += [f"### {t}\n", "<pre>" + html.escape(TEXTS[t]) + "</pre>\n"]
    return "\n".join(out)
open(os.path.join(L, "licenses.md"), "w").write(lic_md())

CSS = """:root{--bg:#eef0f3;--panel:#fff;--ink:#0a0a0c;--ink2:#3a3d45;--mut:#6f7480;--hair:rgba(10,10,12,.1);color-scheme:light}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#0c0d10;--panel:#15171b;--ink:#eef0f3;--ink2:#c3c7cf;--mut:#8b909a;--hair:rgba(238,240,243,.12);color-scheme:dark}}
:root[data-theme="dark"]{--bg:#0c0d10;--panel:#15171b;--ink:#eef0f3;--ink2:#c3c7cf;--mut:#8b909a;--hair:rgba(238,240,243,.12);color-scheme:dark}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased}
header{max-width:820px;margin:0 auto;padding:22px 18px 0;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}
header a{color:var(--ink);text-decoration:none;font-weight:600;letter-spacing:.14em;text-transform:uppercase;font-size:12px}
nav{display:flex;gap:14px;flex-wrap:wrap}nav a{font-weight:500;letter-spacing:0;text-transform:none;font-size:14px;color:var(--mut)}nav a[aria-current]{color:var(--ink)}
main{max-width:820px;margin:18px auto 0;padding:34px clamp(18px,5vw,48px);background:var(--panel);border-radius:22px;box-shadow:0 0 0 .5px var(--hair)}
h1{font-size:clamp(30px,5vw,40px);line-height:1.1;letter-spacing:-.02em;margin:0 0 6px}h2{font-size:21px;margin:38px 0 8px;letter-spacing:-.01em}h3{font-size:17px;margin:26px 0 6px}
p,li{color:var(--ink2)}a{color:var(--ink)}strong{color:var(--ink)}blockquote{margin:18px 0;padding:14px 18px;border-radius:14px;background:var(--bg);border:0}blockquote p{margin:0}
table{width:100%;border-collapse:collapse;font-size:14px;display:block;overflow-x:auto}th,td{text-align:left;vertical-align:top;padding:9px 10px;border-top:1px solid var(--hair)}th{color:var(--mut);font-weight:600}
pre{white-space:pre-wrap;font-size:12.5px;line-height:1.5;background:var(--bg);padding:14px;border-radius:12px;color:var(--ink2)}
footer{max-width:820px;margin:0 auto;padding:22px 18px 48px;font-size:13px;color:var(--mut)}footer a{color:var(--mut)}"""
DOCS = [("privacy", "Privacy"), ("eula", "Terms of Use"), ("terms", "Terms of Service"), ("refunds", "Refunds"), ("licenses", "Licenses"), ("support", "Support")]

def page(slug, title, body, base):
    nav = "".join(f'<a href="{base}{s}"{" aria-current=\"page\"" if s == slug else ""}>{t}</a>' for s, t in DOCS)
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{html.escape(title)} · {V['APP']}</title><meta name="description" content="{html.escape(title)} for {V['APP']}, a product of {html.escape(V['COMPANY'])}.">
<style>{CSS}</style></head><body><header><a href="{base or '/'}">{V['APP']}</a><nav aria-label="Legal">{nav}</nav></header>
<main>{body}</main><footer>{html.escape(V['COMPANY'])} · {html.escape(V['ADDRESS'])} · <a href="mailto:{V['EMAIL']}">{V['EMAIL']}</a></footer></body></html>"""

pages = {}
for slug, _ in DOCS:
    raw = open(os.path.join(L, slug + ".md")).read()
    fm, body = re.match(r"---\n(.*?)\n---\n(.*)", raw, re.S).groups()
    title = re.search(r"title: (.*)", fm).group(1)
    pages[slug] = (title, markdown.markdown(sub(body), extensions=["tables", "sane_lists"]))
# Worker pages use root-relative links (/privacy); the static site uses ../privacy/ style links for GitHub Pages subpaths
ts = {s: page(s, t, b, "/") for s, (t, b) in pages.items()}
open(os.path.join(ROOT, "server/src/legal_pages.ts"), "w").write("// Generated by legal/tools/build.py from legal/*.md. Edit the Markdown, then rebuild.\nexport const LEGAL_PAGES: Record<string, string> = " + json.dumps(ts) + ";\n")
site = os.path.join(ROOT, "site"); os.makedirs(site, exist_ok=True)
for s, (t, b) in pages.items():
    os.makedirs(os.path.join(site, s), exist_ok=True)
    b2 = re.sub(r'href="/(privacy|eula|terms|refunds|licenses|support)"', r'href="../\1/"', b)
    h = page(s, t, b2, "../").replace('href="../privacy"', 'href="../privacy/"')
    for d, _ in DOCS: h = h.replace(f'href="../{d}"', f'href="../{d}/"')
    open(os.path.join(site, s, "index.html"), "w").write(h)
idx = "<h1>Legal &amp; support</h1><p>" + V["APP"] + " is a product of " + html.escape(V["COMPANY"]) + ".</p><ul>" + "".join(f'<li><a href="{s}/">{pages[s][0]}</a></li>' for s, _ in DOCS) + "</ul>"
home = page("", "Legal & support", idx, "").replace('href=""', 'href="./"')
for d, _ in DOCS: home = home.replace(f'href="{d}"', f'href="{d}/"')
open(os.path.join(site, "index.html"), "w").write(home)
open(os.path.join(site, ".nojekyll"), "w").write("")
os.makedirs(os.path.join(ROOT, "app/src/legal"), exist_ok=True)
json.dump({"packages": rows, "native": native, "fonts": fonts, "texts": {k: TEXTS[k] for k in used if k in TEXTS}}, open(os.path.join(ROOT, "app/src/legal/licenses.json"), "w"))
print("built", list(pages), "licenses:", len(rows), "texts:", used)
